color: var(--bs-white);\n  text-decoration: none;\n  background: var(--bs-primary);\n}\n.skip-link:focus {\n  top: 0;\n  outline: 3px solid var(--bs-warning);\n  outline-offset: 2px;\n}\n.skip-link:hover {\n  color: var(--bs-white);\n  text-decoration: none;\n  background: var(--bs-primary-emphasis);\n}\n\n/* Enhanced Focus Indicators - WCAG 2.4.7: Focus Visible */\n.focus-enhanced:focus {\n  outline: 3px solid var(--bs-focus-ring-color, #0d6efd);\n  outline-offset: 2px;\n  box-shadow: 0 0 0 0.25rem rgba(13, 110, 253, 0.25);\n}\n\n/* High Contrast Mode Support */\n@media (prefers-contrast: high) {\n  .card {\n    border: 2px solid;\n  }\n  .btn {\n    border-width: 2px;\n  }\n  .nav-link {\n    border: 1px solid transparent;\n  }\n  .nav-link:hover, .nav-link:focus {\n    border-color: currentcolor;\n  }\n}\n/* Reduced Motion Support - WCAG 2.3.3: Animation from Interactions */\n@media (prefers-reduced-motion: reduce) {\n  *,\n  *::before,\n  *::after {\n    transition-duration: 0.01ms !important;\n    animation-duration: 0.01ms !important;\n    animation-iteration-count: 1 !important;\n    scroll-behavior: auto !important;\n  }\n  .fade {\n    display: block;\n  }\n  .collapse {\n    display: block;\n  }\n}\n/* Screen Reader Only Content */\n.sr-only {\n  position: absolute !important;\n  width: 1px !important;\n  height: 1px !important;\n  padding: 0 !important;\n  margin: -1px !important;\n  overflow: hidden !important;\n  clip: rect(0, 0, 0, 0) !important;\n  white-space: nowrap !important;\n  border: 0 !important;\n}\n\n.sr-only-focusable:focus {\n  position: static !important;\n  width: auto !important;\n  height: auto !important;\n  padding: inherit !important;\n  margin: inherit !important;\n  overflow: visible !important;\n  clip: auto !important;\n  white-space: normal !important;\n}\n\n/* Focus Trap Utilities */\n.focus-trap:focus {\n  box-shadow: 0 0 0 0.25rem rgba(13, 110, 253, 0.25);\n}\n\n/* Accessible Color Combinations - WCAG 1.4.3: Contrast (Minimum) */\n.text-accessible-primary {\n  color: #003d82; /* 4.5:1 contrast on white */\n}\n\n.text-accessible-success {\n  color: #0f5132; /* 4.5:1 contrast on white */\n}\n\n.text-accessible-danger {\n  color: #842029; /* 4.5:1 contrast on white */\n}\n\n.text-accessible-warning {\n  color: #664d03; /* 4.5:1 contrast on white */\n}\n\n/* ARIA Live Regions */\n.live-region {\n  position: absolute;\n  left: -10000px;\n  width: 1px;\n  height: 1px;\n  overflow: hidden;\n}\n.live-region.live-region-visible {\n  position: static;\n  left: auto;\n  width: auto;\n  height: auto;\n  overflow: visible;\n}\n\n/* Enhanced Error States - WCAG 3.3.1: Error Identification */\n.form-control.is-invalid {\n  border-color: var(--bs-danger);\n}\n.form-control.is-invalid:focus {\n  border-color: var(--bs-danger);\n  box-shadow: 0 0 0 0.25rem rgba(220, 53, 69, 0.25);\n}\n\n.invalid-feedback {\n  display: block;\n  width: 100%;\n  margin-top: 0.25rem;\n  font-size: 0.875em;\n  color: var(--bs-danger);\n}\n.invalid-feedback[role=alert] {\n  font-weight: 600;\n}\n\n/* Target Size - WCAG 2.5.8: Target Size (Minimum) */\n.touch-target {\n  min-width: 44px;\n  min-height: 44px;\n}\n.touch-target.touch-target-small {\n  min-width: 24px;\n  min-height: 24px;\n}\n\n/* Table Accessibility */\n.table-accessible th {\n  font-weight: 600;\n  background-color: var(--bs-secondary-bg);\n}\n.table-accessible th[scope=col] {\n  border-bottom: 2px solid var(--bs-border-color);\n}\n.table-accessible th[scope=row] {\n  border-right: 2px solid var(--bs-border-color);\n}\n.table-accessible caption {\n  padding: 0.75rem;\n  font-weight: 600;\n  color: var(--bs-secondary);\n  text-align: left;\n  caption-side: top;\n}\n\n/* Navigation Landmarks */\nnav[role=navigation]:not([aria-label]):not([aria-labelledby])::before {\n  position: absolute;\n  left: -10000px;\n  content: \"Navigation\";\n}\n\n/* Form Fieldset Styling */\nfieldset {\n  padding: 1rem;\n  margin-bottom: 1rem;\n  border: 1px solid var(--bs-border-color);\n}\nfieldset legend {\n  padding: 0 0.5rem;\n  margin-bottom: 0.5rem;\n  font-size: 1.1em;\n  font-weight: 600;\n}\n\n/* Loading States */\n.loading[aria-busy=true] {\n  position: relative;\n  pointer-events: none;\n}\n.loading[aria-busy=true]::after {\n  position: absolute;\n  top: 50%;\n  left: 50%;\n  width: 20px;\n  height: 20px;\n  margin-top: -10px;\n  margin-left: -10px;\n  content: \"\";\n  border: 2px solid var(--bs-primary);\n  border-top-color: transparent;\n  animation: spin 1s linear infinite;\n}\n@media (prefers-reduced-motion: reduce) {\n  .loading[aria-busy=true]::after {\n    border-top-color: var(--bs-primary);\n    animation: none;\n  }\n}\n\n@keyframes spin {\n  to {\n    transform: rotate(360deg);\n  }\n}\n/* Dark Mode Accessibility */\n[data-bs-theme=dark] .text-accessible-primary {\n  color: #6ea8fe;\n}\n[data-bs-theme=dark] .text-accessible-success {\n  color: #75b798;\n}\n[data-bs-theme=dark] .text-accessible-danger {\n  color: #f1aeb5;\n}\n[data-bs-theme=dark] .text-accessible-warning {\n  color: #ffda6a;\n}\n\n/* Print Accessibility */\n@media print {\n  .skip-link,\n  .btn,\n  .nav-link {\n    color: #000 !important;\n    background: transparent !important;\n    border: 1px solid #000 !important;\n  }\n  a[href^=http]::after {\n    font-size: 0.8em;\n    content: \" (\" attr(href) \")\";\n  }\n}\n\n/*# sourceMappingURL=adminlte.css.map */\n","/*!\n *   AdminLTE v4.0.0-beta3\n *   Author: Colorlib\n *   Website: AdminLTE.io <https://adminlte.io>\n *   License: Open source - MIT <https://opensource.org/licenses/MIT>\n */\n\n// Bootstrap Configuration\n// ---------------------------------------------------\n@import \"bootstrap/scss/functions\";\n\n// AdminLTE Configuration\n// ---------------------------------------------------\n@import \"bootstrap-variables\"; // little modified are here\n\n// Bootstrap Configuration\n// ---------------------------------------------------\n@import \"bootstrap/scss/variables\";\n@import \"bootstrap/scss